import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] x = new long[n], y = new long[n];
        HashMap<Long, long[]> rows = new HashMap<>(), cols = new HashMap<>();  // row y -> x range, column x -> y range
        for (int i = 0; i < n; i++) {
            x[i] = r.nextLong();
            y[i] = r.nextLong();
            long[] row = rows.get(y[i]);
            if (row == null) rows.put(y[i], new long[] {x[i], x[i]});
            else { row[0] = Math.min(row[0], x[i]); row[1] = Math.max(row[1], x[i]); }
            long[] col = cols.get(x[i]);
            if (col == null) cols.put(x[i], new long[] {y[i], y[i]});
            else { col[0] = Math.min(col[0], y[i]); col[1] = Math.max(col[1], y[i]); }
        }
        int answer = 0;
        for (int i = 0; i < n; i++) {
            long[] row = rows.get(y[i]), col = cols.get(x[i]);
            if (row[0] < x[i] && x[i] < row[1] && col[0] < y[i] && y[i] < col[1]) answer++;
        }
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

