func main() {
	n := readInt()
	x, y := make([]int, n), make([]int, n)
	rows, cols := map[int][2]int{}, map[int][2]int{} // row y -> x range, column x -> y range
	for i := 0; i < n; i++ {
		x[i], y[i] = readInt(), readInt()
		if r, ok := rows[y[i]]; ok {
			rows[y[i]] = [2]int{min(r[0], x[i]), max(r[1], x[i])}
		} else {
			rows[y[i]] = [2]int{x[i], x[i]}
		}
		if c, ok := cols[x[i]]; ok {
			cols[x[i]] = [2]int{min(c[0], y[i]), max(c[1], y[i])}
		} else {
			cols[x[i]] = [2]int{y[i], y[i]}
		}
	}
	answer := 0
	for i := 0; i < n; i++ {
		r, c := rows[y[i]], cols[x[i]]
		if r[0] < x[i] && x[i] < r[1] && c[0] < y[i] && y[i] < c[1] {
			answer++
		}
	}
	fmt.Println(answer)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
